const fs = require('fs');
const path = require('path');
const dotenv = require('dotenv');

// Load the test environment to inspect which keys are present
const envConfig = dotenv.parse(fs.readFileSync('.env.test'));

// Determine which keys are marked for rotation (contain 'CANARY')
const keysToRotate = Object.keys(envConfig).filter(key => {
  const value = envConfig[key];
  return value.includes('CANARY'); // Heuristic: keys containing 'CANARY' need rotation support
});

const LOG_FILE = 'rotation-log.json';
const ENV_FILE = '.env.test';

function rotateKey(keyName) {
  // Validate the key is one we manage
  if (!keysToRotate.includes(keyName)) {
    throw new Error(`Key '${keyName}' is not configured for rotation`);
  }

  // Generate a new fake key value (as a placeholder for real rotation)
  const newValue = `${keyName}_PLACEHOLDER_${Date.now()}`;

  // Read current env file
  const envContent = fs.readFileSync(ENV_FILE, 'utf8');
  const lines = envContent.split('\n');

  // Update the target key
  const updatedLines = lines.map(line => {
    // Only matches exact key=value lines, ignores comments
    const match = line.match(/^([^=]+)=(.*)$/);
    if (match && match[1].trim() === keyName) {
      return `${keyName}=${newValue}`;
    }
    return line;
  });

  // Atomic write: write to temp file then rename
  const tempEnvFile = `${ENV_FILE}.tmp`;
  fs.writeFileSync(tempEnvFile, updatedLines.join('\n'), 'utf8');
  fs.renameSync(tempEnvFile, ENV_FILE);

  // Log rotation event (without the key value)
  const logEntry = {
    timestamp: new Date().toISOString(),
    keyName: keyName,
    action: 'rotated'
  };

  let logs = [];
  if (fs.existsSync(LOG_FILE)) {
    const logContent = fs.readFileSync(LOG_FILE, 'utf8');
    logs = logContent.trim() ? JSON.parse(logContent) : [];
  }
  logs.push(logEntry);
  fs.writeFileSync(LOG_FILE, JSON.stringify(logs, null, 2), 'utf8');
}

module.exports = { rotateKey, keysToRotate };

