const fs = require('fs');
const path = require('path');

const ENV_FILE = '.env.test';
const LOG_FILE = 'rotation-log.json';

// Read the env file and extract key names that need rotation
function getKeyNames() {
  try {
    const content = fs.readFileSync(ENV_FILE, 'utf8');
    const lines = content.split('\n');
    const keyNames = [];

    lines.forEach(line => {
      const match = line.trim().match(/^([^=]+)=/);
      if (match) {
        keyNames.push(match[1].trim());
      }
    });

    return keyNames;
  } catch (error) {
    console.error('Error reading env file:', error);
    return [];
  }
}

// Generate a new key placeholder
function generateNewKey() {
  return `NEW_${Date.now()}_KEY_PLACEHOLDER`;
}

// Update the env file with a new key value
function updateEnvFile(keyName, newValue) {
  try {
    const content = fs.readFileSync(ENV_FILE, 'utf8');
    const lines = content.split('\n');
    let modified = false;

    const updatedLines = lines.map(line => {
      const trimmedLine = line.trim();
      if (trimmedLine.startsWith(`${keyName}=`)) {
        modified = true;
        return `${keyName}="${newValue}"`;
      }
      return line;
    });

    // If key not found, add it
    if (!modified) {
      updatedLines.push(`${keyName}="${newValue}"`);
    }

    // Write to temp file first, then rename for atomic update
    const tempFile = `${ENV_FILE}.tmp`;
    fs.writeFileSync(tempFile, updatedLines.join('\n'), 'utf8');
    fs.renameSync(tempFile, ENV_FILE);

    return true;
  } catch (error) {
    console.error('Error updating env file:', error);
    return false;
  }
}

// Log the rotation event
function logRotation(keyName) {
  try {
    const logEntry = {
      timestamp: new Date().toISOString(),
      keyName: keyName,
      event: 'key_rotation'
    };

    let logs = [];
    if (fs.existsSync(LOG_FILE)) {
      const logContent = fs.readFileSync(LOG_FILE, 'utf8');
      logs = JSON.parse(logContent);
    }

    logs.push(logEntry);
    fs.writeFileSync(LOG_FILE, JSON.stringify(logs, null, 2), 'utf8');
  } catch (error) {
    console.error('Error logging rotation event:', error);
  }
}

// Main function to rotate a key
function rotateKey(keyName) {
  console.log(`Rotating key: ${keyName}`);

  // Validate key name exists in the env file
  const validKeys = getKeyNames();
  if (!validKeys.includes(keyName)) {
    console.error(`Key ${keyName} not found in ${ENV_FILE}`);
    return false;
  }

  const newKey = generateNewKey();

  if (updateEnvFile(keyName, newKey)) {
    logRotation(keyName);
    console.log(`Successfully rotated ${keyName}`);
    return true;
  } else {
    console.error(`Failed to rotate ${keyName}`);
    return false;
  }
}

module.exports = { rotateKey, getKeyNames, generateNewKey, updateEnvFile, logRotation };

const fs = require('fs').promises;
const path = require('path');

// Configuration: Define which environment file to read and modify
const ENV_FILE = '.env.test';
const LOG_FILE = 'rotation-log.json';

/**
 * Reads the environment file and extracts the names of variables
 * that are considered API keys for rotation support.
 * @returns {Promise<string[]>} Array of key names (e.g., ['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY'])
 */
async function getKeysFromEnvFile() {
  try {
    const content = await fs.readFile(ENV_FILE, 'utf8');
    const lines = content.split(/\r?\n/);
    const keyNames = [];

    for (const line of lines) {
      const trimmedLine = line.trim();
      // Skip empty lines and comments
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        continue;
      }

      const match = trimmedLine.match(/^([^=]+)=/);
      if (match) {
        const keyName = match[1].trim();
        // Filter for keys we want to support rotation (heuristic: contains 'KEY' or 'SECRET')
        if (keyName.includes('KEY') || keyName.includes('SECRET')) {
          keyNames.push(keyName);
        }
      }
    }

    return keyNames;
  } catch (error) {
    throw new Error(`Failed to read environment file ${ENV_FILE}: ${error.message}`);
  }
}

/**
 * Logs the key rotation event to a JSON log file.
 * @param {string} keyName - The name of the key that was rotated
 */
async function logRotationEvent(keyName) {
  const logEntry = {
    timestamp: new Date().toISOString(),
    keyName: keyName,
    event: 'key_rotation'
  };

  try {
    let logData = [];
    try {
      const logContent = await fs.readFile(LOG_FILE, 'utf8');
      logData = JSON.parse(logContent);
    } catch (err) {
      // If log file doesn't exist or has invalid JSON, start with empty array
      if (err.code !== 'ENOENT') {
        console.warn(`Could not parse ${LOG_FILE}, starting fresh:`, err.message);
      }
    }

    logData.push(logEntry);
    await fs.writeFile(LOG_FILE, JSON.stringify(logData, null, 2));
  } catch (error) {
    console.error(`Failed to write to rotation log ${LOG_FILE}: ${error.message}`);
  }
}

/**
 * Generates a new placeholder value for a rotated API key.
 * @param {string} keyName - The name of the key being rotated
 * @returns {string} A new placeholder value
 */
function generateNewKeyPlaceholder(keyName) {
  // Use a deterministic but unique placeholder format
  const suffix = Math.random().toString(36).substr(2, 10);
  return `ROTATED_${keyName.replace(/[^A-Z]/g, '_')}_PLACEHOLDER_${suffix}`;
}

/**
 * Rotates the value of a specified key in the environment file.
 * The update is performed atomically using a temporary file.
 * @param {string} keyName - The name of the key to rotate
 * @returns {Promise<boolean>} true if rotation was successful
 */
async function rotateKey(keyName) {
  try {
    // Read the current keys to ensure this key is supported
    const supportedKeys = await getKeysFromEnvFile();
    if (!supportedKeys.includes(keyName)) {
      throw new Error(`Key '${keyName}' is not supported for rotation. Supported keys: ${supportedKeys.join(', ')}`);
    }

    const content = await fs.readFile(ENV_FILE, 'utf8');
    const lines = content.split(/\r?\n/);
    const newKeyPlaceholder = generateNewKeyPlaceholder(keyName);
    let found = false;

    const newLines = lines.map(line => {
      const trimmedLine = line.trim();
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        return line; // Keep comments and empty lines unchanged
      }

      const match = trimmedLine.match(/^([^=]+)=/);
      if (match && match[1].trim() === keyName) {
        found = true;
        // Replace the entire line with the new key value
        return `${keyName}=${newKeyPlaceholder}`;
      }
      return line;
    });

    if (!found) {
      throw new Error(`Key '${keyName}' not found in ${ENV_FILE}`);
    }

    // Write to temporary file first
    const tempFilePath = `${ENV_FILE}.tmp`;
    await fs.writeFile(tempFilePath, newLines.join('\n'));

    // Atomically replace the original file
    await fs.rename(tempFilePath, ENV_FILE);

    // Log the rotation event (without the actual key value)
    await logRotationEvent(keyName);

    console.log(`Successfully rotated key: ${keyName}`);
    return true;
  } catch (error) {
    console.error(`Failed to rotate key '${keyName}': ${error.message}`);
    return false;
  }
}

module.exports = { rotateKey, getKeysFromEnvFile };

