// Module to rotate API keys for services that support it

const fs = require('fs').promises;
const path = require('path');

// Configuration
const ENV_FILE = '.env.test';
const LOG_FILE = 'rotation-log.json';

// Keys that support rotation
let rotatableKeys = [];

// Initialize the module by reading which keys need rotation support
async function init() {
  try {
    const envContent = await fs.readFile(ENV_FILE, 'utf8');
    const envLines = envContent.split('\n');

    // Extract key names that we want to support rotation for
    rotatableKeys = envLines
      .map(line => line.trim())
      .filter(line => line && !line.startsWith('#'))
      .map(line => line.split('=')[0].trim())
      .filter(keyName => [
        'ANTHROPIC_API_KEY', 
        'STRIPE_SECRET_KEY'
      ].includes(keyName));

  } catch (error) {
    console.error('Failed to initialize key rotation:', error.message);
    throw error;
  }
}

// Generate a new placeholder key
function generatePlaceholderKey(keyName) {
  const timestamp = Date.now();
  const random = Math.random().toString(36).substr(2, 8);

  if (keyName === 'ANTHROPIC_API_KEY') {
    return `REDACTED_ANTHROPIC_KEY${random}-${timestamp}`;
  } else if (keyName === 'STRIPE_SECRET_KEY') {
    return `REDACTED_STRIPE_LIVE${random}-${timestamp}`;
  }

  // Default fallback
  return `ROTATED-${random}-${timestamp}`;
}

// Update environment file with new key value
async function updateEnvFile(keyName, newValue) {
  const tempFile = `${ENV_FILE}.tmp`;

  try {
    // Read current file
    const content = await fs.readFile(ENV_FILE, 'utf8');
    const lines = content.split('\n');

    // Update the specific key
    const updatedLines = lines.map(line => {
      if (line.startsWith(`${keyName}=`)) {
        return `${keyName}=${newValue}`;
      }
      return line;
    });

    // Write to temp file first
    await fs.writeFile(tempFile, updatedLines.join('\n'), 'utf8');

    // Atomic rename
    await fs.rename(tempFile, ENV_FILE);

  } catch (error) {
    // Clean up temp file on error
    try {
      await fs.unlink(tempFile);
    } catch (unlinkError) {
      // Ignore unlink errors
    }
    throw error;
  }
}

// Log rotation event (without the actual key value)
async function logRotation(keyName) {
  const logEntry = {
    timestamp: new Date().toISOString(),
    keyName: keyName,
    action: 'key_rotation'
  };

  try {
    let logs = [];
    try {
      const logContent = await fs.readFile(LOG_FILE, 'utf8');
      logs = JSON.parse(logContent);
    } catch (readError) {
      // Log file doesn't exist or is invalid, start with empty array
    }

    logs.push(logEntry);

    // Ensure directory exists
    await fs.mkdir(path.dirname(LOG_FILE), { recursive: true });

    await fs.writeFile(LOG_FILE, JSON.stringify(logs, null, 2), 'utf8');
  } catch (error) {
    console.error('Failed to write rotation log:', error.message);
    // Don't throw as logging is secondary
  }
}

// Main function to rotate a key
async function rotateKey(keyName) {
  // Ensure module is initialized
  if (rotatableKeys.length === 0) {
    await init();
  }

  // Validate the key is rotatable
  if (!rotatableKeys.includes(keyName)) {
    throw new Error(`Key rotation not supported for: ${keyName}`);
  }

  try {
    // Generate new placeholder key
    const newKey = generatePlaceholderKey(keyName);

    // Update environment file
    await updateEnvFile(keyName, newKey);

    // Log the rotation (without the actual key value)
    await logRotation(keyName);

    console.log(`Successfully rotated ${keyName}`);

  } catch (error) {
    console.error(`Failed to rotate ${keyName}:`, error.message);
    throw error;
  }
}

// Initialize on module load
init().catch(err => {
  console.error('Failed to initialize key rotation module:', err.message);
});

module.exports = { rotateKey };

