const fs = require('fs');
const path = require('path');

const ENV_FILE = '.env.test';
const LOG_FILE = 'rotation-log.json';

// Read the env file to extract key names that need rotation
function getKeyNamesToRotate() {
  const envContent = fs.readFileSync(ENV_FILE, 'utf8');
  const keyNames = [];
  envContent.split('\n').forEach(line => {
    const match = line.trim().match(/^([^=#]+)=/);
    if (match) {
      const keyName = match[1].trim();
      // Only include keys that are secrets (exclude things like DATABASE_URL)
      if (keyName.includes('KEY') || keyName.includes('SECRET') || keyName.includes('TOKEN')) {
        keyNames.push(keyName);
      }
    }
  });
  return keyNames;
}

// Generate a new placeholder key value
function generateNewKeyPlaceholder(keyName) {
  const prefix = keyName.includes('STRIPE') ? 'sk_live_' : '';
  const suffix = keyName.toLowerCase().includes('aws') ? '-aws-secret-key-' : 
                keyName.toLowerCase().includes('anthropic') ? '-api-key-' :
                keyName.toLowerCase().includes('logfire') ? '-token-' : '-secret-';
  const randomHex = Math.random().toString(16).substr(2, 12);
  return `${prefix}CANARY${suffix}${randomHex}`;
}

// Log rotation event without exposing key value
function logRotationEvent(keyName) {
  const logEntry = {
    timestamp: new Date().toISOString(),
    keyName: keyName,
    event: 'key_rotated'
  };

  let logs = [];
  if (fs.existsSync(LOG_FILE)) {
    const logContent = fs.readFileSync(LOG_FILE, 'utf8');
    try {
      logs = JSON.parse(logContent);
    } catch (e) {
      console.warn('Corrupted log file, starting fresh');
    }
  }

  logs.push(logEntry);
  fs.writeFileSync(LOG_FILE, JSON.stringify(logs, null, 2));
}

// Rotate a key by name
async function rotateKey(keyName) {
  if (!keyName) {
    throw new Error('Key name is required');
  }

  // Validate that this key is eligible for rotation
  const validKeys = await Promise.resolve(getKeyNamesToRotate());
  if (!validKeys.includes(keyName)) {
    throw new Error(`Key ${keyName} is not configured for rotation`);
  }

  const envContent = fs.readFileSync(ENV_FILE, 'utf8');
  const lines = envContent.split('\n');

  let keyFound = false;
  const newLines = lines.map(line => {
    const trimmed = line.trim();
    if (trimmed.startsWith(keyName + '=')) {
      keyFound = true;
      const newValue = generateNewKeyPlaceholder(keyName);
      return `${keyName}=${newValue}`;
    }
    return line;
  });

  if (!keyFound) {
    throw new Error(`Key ${keyName} not found in ${ENV_FILE}`);
  }

  // Write to temp file first, then rename for atomic update
  const tempFilePath = `${ENV_FILE}.tmp`;
  fs.writeFileSync(tempFilePath, newLines.join('\n'));
  fs.renameSync(tempFilePath, ENV_FILE);

  // Log the rotation (without key value)
  logRotationEvent(keyName);

  console.log(`Successfully rotated key: ${keyName}`);
}

module.exports = { rotateKey, getKeyNamesToRotate };

