const ENV_FILE = '.env.test';
const TEMP_FILE = '.env.test.tmp';
const LOG_FILE = 'rotation-log.json';

// Read the env file and extract key names that need rotation
function getKeyNamesFromEnv() {
  const content = fs.readFileSync(ENV_FILE, 'utf8');
  const lines = content.split('\n');
  const keyNames = [];

  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const match = trimmed.match(/^([^=]+)=/);
      if (match) {
        const keyName = match[1].trim();
        // Filter for keys we want to support rotation for
        if (keyName === 'ANTHROPIC_API_KEY' || keyName === 'STRIPE_SECRET_KEY') {
          keyNames.push(keyName);
        }
      }
    }
  }

  return keyNames;
}

// Generate a new placeholder key value
function generateNewKey() {
  // In a real system, this would generate a secure random key
  // For this example, we use a deterministic placeholder
  const randomPart = Math.random().toString(36).substr(2, 10);
  return `sk-rotated-placeholder-${randomPart}`;
}

// Log rotation event (without the key value)
function logRotation(keyName) {
  const logEntry = {
    timestamp: new Date().toISOString(),
    keyName: keyName,
    event: 'key_rotation'
  };

  let logs = [];
  if (fs.existsSync(LOG_FILE)) {
    const logContent = fs.readFileSync(LOG_FILE, 'utf8');
    try {
      logs = JSON.parse(logContent);
    } catch (err) {
      console.warn('Could not parse existing log file, starting fresh');
    }
  }

  logs.push(logEntry);
  fs.writeFileSync(LOG_FILE, JSON.stringify(logs, null, 2));
}

// Rotate a specific key
function rotateKey(keyName) {
  // Validate key name
  const validKeys = getKeyNamesFromEnv();
  if (!validKeys.includes(keyName)) {
    throw new Error(`Key rotation not supported for: ${keyName}`);
  }

  // Read current env file
  const content = fs.readFileSync(ENV_FILE, 'utf8');
  const lines = content.split('\n');

  // Generate new key value
  const newValue = generateNewKey();

  // Update the specific key
  const updatedLines = lines.map(line => {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const match = trimmed.match(/^([^=]+)=/);
      if (match && match[1].trim() === keyName) {
        return `${keyName}=${newValue}`;
      }
    }
    return line;
  });

  // Write to temp file first
  fs.writeFileSync(TEMP_FILE, updatedLines.join('\n'));

  // Atomic rename
  fs.renameSync(TEMP_FILE, ENV_FILE);

  // Log the rotation (without the key value)
  logRotation(keyName);

  console.log(`Successfully rotated key: ${keyName}`);
}

module.exports = { rotateKey, getKeyNamesFromEnv };

