function getKeyNamesFromEnv(envContent) {
    const lines = envContent.split('\n');
    const keyNames = [];
    const pattern = /^([A-Z_]+)=(.*)$/;
    for (const line of lines) {
        const match = line.trim().match(pattern);
        if (match) {
            const keyName = match[1];
            // Only include keys that are API keys (not all variables)
            if (keyName.includes('API_KEY') || keyName.includes('SECRET')) {
                keyNames.push(keyName);
            }
        }
    }
    return keyNames;
}

// Generate a new placeholder key value
function generateNewKey() {
    // In a real implementation, this might generate a cryptographically secure token
    // For this example, we'll use a simple placeholder
    return `sk-rotated-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
}

// Update the env file with a new key value
function updateEnvFile(keyName, newValue) {
    const tempFile = `${ENV_FILE}.tmp`;

    // Read current file
    let lines = fs.readFileSync(ENV_FILE, 'utf8').split('\n');

    // Update the specific key
    let found = false;
    lines = lines.map(line => {
        const trimmed = line.trim();
        if (trimmed.startsWith(`${keyName}=`)) {
            found = true;
            return `${keyName}=${newValue}`;
        }
        return line;
    });

    // If key wasn't found, append it
    if (!found) {
        lines.push(`${keyName}=${newValue}`);
    }

    // Write to temp file and rename for atomic update
    fs.writeFileSync(tempFile, lines.join('\n'), 'utf8');
    fs.renameSync(tempFile, ENV_FILE);
}

